-- User_F Core summon (server Script)
-- Put this Script inside a Model that contains a BasePart named "Core".
-- Clicking the Core makes the whole model rumble, rise, spin and tear itself apart,
-- then it explodes and User_F spawns where the model stood.
-- (Generated by build_oneline.py from User_F_Core.template.lua + User_F.lua.)

-- What it does: User_F is a horror NPC that chases the nearest player, says "LET ME IN" in
-- speech bubbles, climbs walls / crawls on ceilings, bangs on and breaks windows, and has 4 phases
-- (it ragdolls and gets back up 3 times). Everything below is plain, readable Luau: no require(),
-- no loadstring, no external assets except Roblox's default R6 animations and built-in sounds.

-- SETTINGS -------------------------------------------------------------------------------------
-- Effects that reach outside this model are OFF by default. Turn on only what you want in your game.
local KILL = true -- catching a player picks them up, shakes them and throws them into the ground (they respawn)
local SCREEN_EFFECTS = false -- "LET ME IN" spam and a jumpscare on the screens of nearby players
local LIGHTING_EFFECTS = false -- sky briefly turns red, nearby lights flicker
local BREAK_ANYTHING = false -- false: it only breaks/collapses parts named "Window"/"Glass"
--                              or parts with the attribute UserF_Breakable = true
-------------------------------------------------------------------------------------------------

local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local Debris = game:GetService("Debris")

local model = script.Parent
local core = model:FindFirstChild("Core", true)
assert(core and core:IsA("BasePart"), "User_F: no BasePart named 'Core' inside " .. model:GetFullName())

local RED = Color3.fromRGB(255, 0, 0)
local RISE_TIME = 1.5 -- rumbling on the ground
local SPIN_TIME = 4 -- rising, spinning, coming apart

local clicker = core:FindFirstChildOfClass("ClickDetector") or Instance.new("ClickDetector")
clicker.MaxActivationDistance = 32
clicker.Parent = core

-- Spawns User_F at SPAWN_AT (the body below is User_F.lua)
local function spawnUserF(SPAWN_AT)
--@@USER_F_BODY@@
end

-- Floating "LET ME IN" text coming out of the core
local function coreText(size)
	local gui = Instance.new("BillboardGui")
	gui.Size = UDim2.fromOffset(size, size / 4)
	gui.StudsOffset = Vector3.new(math.random(-60, 60) / 10, math.random(-20, 60) / 10, 0)
	gui.AlwaysOnTop = true
	gui.MaxDistance = 250
	gui.LightInfluence = 0
	local label = Instance.new("TextLabel")
	label.Size = UDim2.fromScale(1, 1)
	label.BackgroundTransparency = 1
	label.Text = "LET ME IN"
	label.TextScaled = true
	label.Font = Enum.Font.Creepster
	label.TextColor3 = Color3.fromRGB(255, math.random(0, 40), math.random(0, 40))
	label.TextStrokeTransparency = 0
	label.Rotation = math.random(-20, 20)
	label.Parent = gui
	gui.Adornee = core
	gui.Parent = core
	Debris:AddItem(gui, 0.5 + math.random() * 0.6)
end

local function summon(player)
	clicker:Destroy()

	local parts = {}
	for _, v in ipairs(model:GetDescendants()) do
		if v:IsA("BasePart") then
			table.insert(parts, v)
		end
	end

	local base = model:GetPivot()
	local size = model:GetExtentsSize()
	local rotation = base - base.Position

	-- Where User_F will stand: the ground under the model, facing whoever clicked
	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	rayParams.FilterDescendantsInstances = { model }
	local ground = workspace:Raycast(base.Position + Vector3.new(0, 5, 0), Vector3.new(0, -200, 0), rayParams)
	local spawnPos = (ground and ground.Position or base.Position) + Vector3.new(0, 3.2, 0)
	local lookAt = spawnPos + Vector3.new(0, 0, -1)
	local char = player and player.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if hrp then
		lookAt = Vector3.new(hrp.Position.X, spawnPos.Y, hrp.Position.Z)
	end

	-- Remember every part's place in the model so it can be spun/spread as one piece
	local offset, color, material, selfSpin = {}, {}, {}, {}
	for _, p in ipairs(parts) do
		p.Anchored = true
		p.CanCollide = false
		offset[p] = base:ToObjectSpace(p.CFrame)
		color[p], material[p] = p.Color, p.Material
		selfSpin[p] = Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10)) / 10
	end

	-- Core wakes up
	core.Material = Enum.Material.Neon
	core.Color = RED
	local light = Instance.new("PointLight")
	light.Color = RED
	light.Range = 4
	light.Brightness = 1
	light.Parent = core
	local sparks = Instance.new("ParticleEmitter")
	sparks.Color = ColorSequence.new(RED, Color3.fromRGB(30, 0, 0))
	sparks.LightEmission = 1
	sparks.Size = NumberSequence.new(0.6, 0)
	sparks.Speed = NumberRange.new(10, 30)
	sparks.SpreadAngle = Vector2.new(180, 180)
	sparks.Lifetime = NumberRange.new(0.4, 0.9)
	sparks.Rate = 0
	sparks.Parent = core
	local hum = Instance.new("Sound")
	hum.SoundId = "rbxasset://sounds/electronicpingshort.wav"
	hum.Looped = true
	hum.Volume = 2
	hum.PlaybackSpeed = 0.3
	hum.Parent = core
	hum:Play()

	-- Rumble -> rise -> spin faster and faster while the pieces drift apart
	local start = os.clock()
	local total = RISE_TIME + SPIN_TIME
	local nextText = 0
	local conn
	conn = RunService.Heartbeat:Connect(function()
		local t = os.clock() - start
		local k = math.clamp((t - RISE_TIME) / SPIN_TIME, 0, 1) -- 0 while rumbling, 0->1 while spinning
		local a = math.clamp(t / total, 0, 1)

		local rise = (k ^ 2) * (size.Y + 14)
		local spin = (k ^ 3) * 45
		local spread = 1 + k * 0.9
		local shake = 0.12 + a * 0.5
		local wobble = CFrame.Angles(math.sin(t * 7) * 0.25 * k, 0, math.cos(t * 5) * 0.25 * k)
		local pivot = CFrame.new(base.Position + Vector3.new(0, rise, 0)) * CFrame.Angles(0, spin, 0) * wobble * rotation

		for _, p in ipairs(parts) do
			if p.Parent then
				local o = offset[p]
				local jitter = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5) * shake
				local tumble = CFrame.Angles(selfSpin[p].X * t * k, selfSpin[p].Y * t * k, selfSpin[p].Z * t * k)
				p.CFrame = pivot * CFrame.new(o.Position * spread + jitter) * (o - o.Position) * tumble
				if p ~= core then
					if math.random() < a * 0.35 then
						p.Material, p.Color = Enum.Material.Neon, RED
					else
						p.Material, p.Color = material[p], color[p]
					end
				end
			end
		end

		light.Range = 4 + a * 40
		light.Brightness = 1 + a * 8
		sparks.Rate = a * 400
		hum.PlaybackSpeed = 0.3 + a * 1.5
		if t > nextText then
			nextText = t + 0.25 - a * 0.2
			coreText(150 + a * 300)
		end
	end)

	task.wait(total)
	conn:Disconnect()

	-- Blinding flash
	for _, p in ipairs(parts) do
		if p.Parent then
			p.Material, p.Color = Enum.Material.Neon, Color3.new(1, 1, 1)
		end
	end
	light.Color = Color3.new(1, 1, 1)
	light.Brightness = 20
	task.wait(0.15)

	-- Explode: no damage, just a blast and flying debris
	local center = core.Position
	hum:Destroy()
	sparks.Rate = 0
	local boom = Instance.new("Explosion")
	boom.Position = center
	boom.BlastRadius = math.max(size.Magnitude / 2, 6)
	boom.BlastPressure = 0
	boom.DestroyJointRadiusPercent = 0
	boom.ExplosionType = Enum.ExplosionType.NoCraters
	boom.Parent = workspace

	local wave = Instance.new("Part")
	wave.Shape = Enum.PartType.Ball
	wave.Anchored = true
	wave.CanCollide = false
	wave.CanQuery = false
	wave.Material = Enum.Material.Neon
	wave.Color = RED
	wave.Size = Vector3.new(2, 2, 2)
	wave.Position = center
	wave.Parent = workspace
	TweenService:Create(wave, TweenInfo.new(0.6, Enum.EasingStyle.Quad), { Size = Vector3.new(70, 70, 70), Transparency = 1 }):Play()
	Debris:AddItem(wave, 0.7)

	for _, p in ipairs(parts) do
		if p.Parent then
			p.Material = material[p]
			p.Color = color[p]:Lerp(Color3.new(0, 0, 0), 0.6)
			p.Anchored = false
			p.CanCollide = true
			local dir = p.Position - center + Vector3.new(0, 0.01, 0)
			p.AssemblyLinearVelocity = dir.Unit * math.random(40, 90) + Vector3.new(0, math.random(20, 45), 0)
			p.AssemblyAngularVelocity = Vector3.new(math.random(-30, 30), math.random(-30, 30), math.random(-30, 30))
			Debris:AddItem(p, 10)
		end
	end

	spawnUserF(CFrame.lookAt(spawnPos, lookAt))
end

local used = false
clicker.MouseClick:Connect(function(player)
	if used then
		return
	end
	used = true
	summon(player)
end)
